class PrivateLotStrategySystem(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}

        for ticker in self.tickers:
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_bars = RollingWindow[TradeBar](101)
        self.aapl_closes = RollingWindow[float](4)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.register_indicator(self.aapl, self.aapl_rsi, Resolution.DAILY)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        spy_bar = data.bars[self.spy]
        aapl_bar = data.bars[self.aapl]

        self.spy_bars.add(spy_bar)
        self.aapl_closes.add(aapl_bar.close)

        if not self._all_rules_ready():
            return

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and self._spy_crossed_below_sma_100():
            self.market_order(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self._spy_crossed_above_sma_100():
            shares = int((0.40 * self.portfolio.total_portfolio_value) // spy_bar.close)
            if shares > 0:
                self.market_order(self.spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self._aapl_red_for_three_days():
            if self.portfolio.cash >= 20_000:
                shares = int(20_000 // aapl_bar.close)
                if shares > 0:
                    self.market_order(self.aapl, shares)
                    self.strategy_b_shares = shares

    def _all_rules_ready(self) -> bool:
        return (
            self.spy_bars.is_ready
            and self.aapl_closes.is_ready
            and self.aapl_rsi.is_ready
        )

    def _spy_crossed_above_sma_100(self) -> bool:
        current_close = self.spy_bars[0].close
        previous_close = self.spy_bars[1].close

        current_sma = sum(self.spy_bars[i].close for i in range(100)) / 100.0
        previous_sma = sum(self.spy_bars[i].close for i in range(1, 101)) / 100.0

        return current_close > current_sma and previous_close <= previous_sma

    def _spy_crossed_below_sma_100(self) -> bool:
        current_close = self.spy_bars[0].close
        previous_close = self.spy_bars[1].close

        current_sma = sum(self.spy_bars[i].close for i in range(100)) / 100.0
        previous_sma = sum(self.spy_bars[i].close for i in range(1, 101)) / 100.0

        return current_close < current_sma and previous_close >= previous_sma

    def _aapl_red_for_three_days(self) -> bool:
        return (
            self.aapl_closes[0] < self.aapl_closes[1]
            and self.aapl_closes[1] < self.aapl_closes[2]
            and self.aapl_closes[2] < self.aapl_closes[3]
        )
