class PrivateLotStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl, 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.previous_close = {}
        self.red_streak = 0
        self.previous_spy_sma = None

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        bars_present = {
            ticker: data.Bars.ContainsKey(symbol)
            for ticker, symbol in self.symbols.items()
        }

        if bars_present["AAPL"]:
            aapl_close = data.Bars[self.aapl].Close
            if self.aapl in self.previous_close:
                if aapl_close < self.previous_close[self.aapl]:
                    self.red_streak += 1
                else:
                    self.red_streak = 0
            self.previous_close[self.aapl] = aapl_close

        for ticker, symbol in self.symbols.items():
            if ticker != "AAPL" and bars_present[ticker]:
                self.previous_close[symbol] = data.Bars[symbol].Close

        all_bars_present = all(bars_present.values())

        if not all_bars_present:
            if bars_present["SPY"] and self.spy_sma.IsReady:
                self.previous_spy_sma = self.spy_sma.Current.Value
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        history_ready = (
            self.spy_sma.IsReady
            and self.aapl_rsi.IsReady
            and self.previous_spy_sma is not None
            and self.spy in self.previous_close
        )

        previous_spy_close = self.previous_close[self.spy]

        if history_ready:
            # Sells before buys.
            if (
                self.strategy_a_lot > 0
                and previous_spy_close >= self.previous_spy_sma
                and spy_close < self.spy_sma.Current.Value
            ):
                self.MarketOrder(self.spy, -self.strategy_a_lot)
                self.strategy_a_lot = 0

            if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_lot)
                self.strategy_b_lot = 0

            if (
                self.strategy_a_lot == 0
                and previous_spy_close <= self.previous_spy_sma
                and spy_close > self.spy_sma.Current.Value
            ):
                quantity = int(
                    float(self.Portfolio.TotalPortfolioValue) * 0.40 / float(spy_close)
                )
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_lot = quantity

            if self.strategy_b_lot == 0 and self.red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    quantity = int(20000 / float(aapl_close))
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)
                        self.strategy_b_lot = quantity

        self.previous_spy_sma = (
            self.spy_sma.Current.Value if self.spy_sma.IsReady else None
        )
        self.previous_close[self.spy] = spy_close
